const today = new Date();
const daysAgo = (n) => new Date(today.getTime() - n*86400000).toISOString().slice(0,10);
const leads = [
  { name: "Ryan Ellis", company: "Red Egg Marketing", email: "ryan@redeggmarketing.com", stage: "proposal_sent", lastContactDate: daysAgo(3), touches: 1, score: 8 },
  { name: "Natalie Henley", company: "V9 Digital", email: "info@v9digital.com", stage: "new", lastContactDate: daysAgo(4), touches: 1, score: 7 },
  { name: "Neil Welsh", company: "Silverback Strategies", email: "info@silverbackstrategies.com", stage: "proposal_sent", lastContactDate: daysAgo(7), touches: 2, score: 6 }
];
return leads.map(l => ({ json: { ...l, EventKey: "followup:" + l.email + ":" + today.toISOString().slice(0,10) } }));

const l = $json;
const today = new Date();
const last = new Date(l.lastContactDate);
const daysSince = Math.floor((today - last) / 86400000);
const cadence = {
  "new": [3],
  "proposal_sent": [3, 7, 14],
  "hot": [1, 3],
  "nurture": [30]
};
const schedule = cadence[l.stage] || [7];
const touches = l.touches || 0;
const nextTouch = schedule[Math.min(touches, schedule.length - 1)];
const isDue = daysSince >= nextTouch && touches < schedule.length;
const maxedOut = touches >= schedule.length;
let message = "";
if (l.stage === "new") {
  message = "Hi " + l.name.split(' ')[0] + ", just bumping this in case it got buried. I built an n8n workflow that automates [their process]. Happy to send a 3-min demo. No pressure.";
} else if (l.stage === "proposal_sent") {
  message = "Hi " + l.name.split(' ')[0] + ", following up on the proposal I sent. Any questions? Happy to jump on a quick call to walk through it.";
} else if (l.stage === "hot") {
  message = "Hi " + l.name.split(' ')[0] + ", checking in — ready to lock in a spot? I'm booking projects for next month.";
} else {
  message = "Hi " + l.name.split(' ')[0] + ", hope you're well. If [process] is still a pain point, I'd love to help.";
}
return { json: { ...l, daysSince, touches, isDue, maxedOut, followUpMessage: message,
  newStage: maxedOut ? "nurture" : l.stage } };

